mapper.select:

SELECT l.id,l.entry_type,l.lifecycle_status,l.deleted_at,l.purge_after,l.version,
       (SELECT count(*) FROM expense_adjustment a WHERE a.original_expense_id=l.id) AS linked_count
  FROM ledger_entry l WHERE l.id=#{p.id}


SELECT a.id,'ADJUSTMENT' AS entry_type,a.status AS lifecycle_status,a.deleted_at,a.purge_after,a.version,
       0 AS linked_count
  FROM expense_adjustment a WHERE a.id=#{p.id}

mapper.update:

UPDATE ledger_entry SET lifecycle_status='TRASHED',deleted_at=#{p.now},
       purge_after=#{p.purgeAfter},updated_at=#{p.now},version=version+1
 WHERE id=#{p.id} AND lifecycle_status='ACTIVE' AND version=#{p.version}


UPDATE ledger_entry SET lifecycle_status='ACTIVE',deleted_at=NULL,purge_after=NULL,
       updated_at=#{p.now},version=version+1
 WHERE id=#{p.id} AND lifecycle_status='TRASHED' AND purge_after>#{p.now} AND version=#{p.version}


UPDATE expense_adjustment SET status='TRASHED',deleted_at=#{p.now},
       purge_after=#{p.purgeAfter},updated_at=#{p.now},version=version+1
 WHERE id=#{p.id} AND status='EFFECTIVE' AND version=#{p.version}
